","1784269864031"],"storeSupport":["1783937559655","1783940381028","1783940779626","1784009241799","1784091742083","1784102822192","1784099536705","1784267440078","1784267534664","1784267551578","1784292521328","1784291312686","1784351332154","1784372499131","1784378223009","1784457912186","1784692678852","1784700283937","1784700329825","1784700219729","1784712189491","1785483454948","1785543433129","1785544422658","1785549740704","1785549836217","1785549818910","1785552423330","1785552677276","1785552665397","1785415710060","1785399183638","1785398898167","1785398969501","1785555925961","1785556560867","1785555905857","1785556235988","1785560662536","1785560800907","1785639901906"],"_doorSlots":{"2026-07-13":["14:00:00-15:00:00","18:00:00-19:00:00"],"2026-07-18":["14:00:00-15:00:00"],"2026-07-20":["10:00:00-11:00:00","14:00:00-15:00:00"],"2026-07-22":["15:00:00-16:00:00"],"2026-07-26":["12:00:00-13:00:00"],"2026-08-03":["15:00:00-16:00:00","17:00:00-18:00:00"]}},"_lockedMonths":["2026-07","2026-06"]}'::jsonb,
    updated_at = NOW(),
    updated_by = COALESCE(current_setting('request.jwt.claims', true)::json->>'email', 'restore_july_2026')
WHERE id = 'main';

-- 3) 同步设置触发器需要的 updated_at / updated_by（双保险）
UPDATE public.app_data
SET updated_at = NOW(),
    updated_by = 'restore_july_2026'
WHERE id = 'main';

-- 4) 验证：检查 _lockedMonths 已写入，staff 数与 17:23 一致
DO $$
DECLARE
  v_locked jsonb;
  v_staff_count int;
  v_ratings_july_count int;
BEGIN
  v_locked := (SELECT data->'_lockedMonths' FROM public.app_data WHERE id='main');
  v_staff_count := (SELECT jsonb_array_length(data->'staff') FROM public.app_data WHERE id='main');
  v_ratings_july_count := (
    SELECT jsonb_array_length(COALESCE(data->'ratings', '[]'::jsonb))
    FROM public.app_data WHERE id='main'
  );
  -- 注意：ratings 是全月历史数组，没按月分键；这里仅打印不强制。
  RAISE NOTICE '✓ 还原完成';
  RAISE NOTICE '  _lockedMonths = %', v_locked;
  RAISE NOTICE '  staff 数量    = %', v_staff_count;
  RAISE NOTICE '  ratings 总数  = %  (含历史月份，非强制检查)', v_ratings_july_count;
  IF v_locked IS NULL OR jsonb_array_length(v_locked) < 1 THEN
    RAISE EXCEPTION '✗ _lockedMonths 未写入，请检查 data 字段更新是否成功';
  END IF;
  IF v_staff_count < 20 THEN
    RAISE WARNING '⚠ staff 数偏少（%），可能 data 写入异常，请人工核查', v_staff_count;
  END IF;
END $$;

-- 5) 列出最终状态（可选：跑完后肉眼对照）
SELECT
  id,
  updated_at,
  updated_by,
  data->'_lockedMonths' AS locked_months,
  CASE WHEN jsonb_typeof(data->'staff') = 'array'
       THEN jsonb_array_length(data->'staff') END AS staff_count,
  -- availability.months['YYYY-MM'].data 是「按人名索引的对象」，不是数组
  (SELECT count(*) FROM jsonb_object_keys(
     data->'availability'->'months'->'2026-07'->'data')) AS avail_07_staff,
  CASE WHEN jsonb_typeof(data->'performanceData'->'july'->'records') = 'array'
       THEN jsonb_array_length(data->'performanceData'->'july'->'records') END AS perf_07_records,
  CASE WHEN jsonb_typeof(data->'customerReviews') = 'array'
       THEN jsonb_array_length(data->'customerReviews') END AS reviews_total,
  CASE WHEN jsonb_typeof(data->'doorSchedule') = 'array'
       THEN jsonb_array_length(data->'doorSchedule') END AS door_total,
  CASE WHEN jsonb_typeof(data->'storeSupport') = 'array'
       THEN jsonb_array_length(data->'storeSupport') END AS support_total
FROM public.app_data
WHERE id = 'main';

COMMIT;
